    const disposedNames = [];
    manager.supervisors.set("s-x", {
      disposed: false,
      reconnectTimer: setTimeout(() => {}, 60_000),
      syncChain: Promise.resolve(),
      toolDisposers: new Map([["t", () => disposedNames.push("t")]]),
    });
    await manager.dispose();
    assert.deepEqual(disposedNames, ["t"]);
